import assert from 'node:assert/strict';
import {createServer} from 'node:http';
import {sha256} from '../../packages/contracts/src/index.ts';
import {meridianModule} from './meridian-flow.ts';

export async function reviewValidationModule(h:any,options:{id?:string;flowId?:string;version?:string;transition?:string;interpreter?:string;noHooks?:boolean;initialState?:unknown;approve?:boolean;providerPrefix?:'meridian'|'alternate'}={}){
 const fixture=await meridianModule(options.version??'2.0.0',options.id??'meridian',options.flowId??'meridian-execute');
 const rewrite=(path:string,text:string)=>{const file=fixture.files.find(entry=>entry.path===path);assert.ok(file);file.base64=Buffer.from(text).toString('base64');};
 if(options.providerPrefix){const file=fixture.files.find(entry=>entry.path==='tools/transition.ts')!,text=Buffer.from(file.base64,'base64').toString();rewrite(file.path,text.replaceAll(/(?:meridian|alternate)_prepare/g,options.providerPrefix+'_prepare').replaceAll(/(?:meridian|alternate)_submit/g,options.providerPrefix+'_submit'));}if(options.transition)rewrite('tools/transition.ts',options.transition);if(options.interpreter)rewrite('tools/interpret.ts',options.interpreter);
 if(options.noHooks){const file=fixture.files.find(entry=>entry.path==='product-line.json')!,manifest=JSON.parse(Buffer.from(file.base64,'base64').toString());manifest.hooks=[];rewrite(file.path,JSON.stringify(manifest));}
 if(options.initialState!==undefined){const file=fixture.files.find(entry=>entry.path==='flows/execution.json')!,flow=JSON.parse(Buffer.from(file.base64,'base64').toString());flow.initialState=options.initialState;rewrite(file.path,JSON.stringify(flow));}
 for(const file of fixture.files)file.sha256=sha256(Buffer.from(file.base64,'base64'));fixture.module.files=fixture.files.map(({path,sha256})=>({path,sha256}));fixture.module.digest=sha256(fixture.files.map(file=>`${file.sha256}  ${file.path}\n`).join(''));
 const response=await h.raw('/v1/modules/install',{token:await h.login(),headers:{'x-scope-id':'scp_lab'},body:fixture});assert.equal(response.status,201,JSON.stringify(response.body));const method=response.body.data;
 if(options.approve!==false)await h.request(`/v1/assets/${method.assetId}/lifecycle`,{version:method.assetVersion,sha256:method.assetSha256,state:'approved'},'bob');return method;
}

export const pureOriginalTransition="export function transition(input){if(input.state.stage==='parse')return {schema:'hub-execution-transition/1',state:{stage:'deliver'},actions:[{kind:'tool.call',stepId:'parse-original',occurrence:0,path:'tools/interpret.ts',export:'interpret',args:[input.currentInput.value.value.provenance],byteSlots:['original']}]};const parsed=input.observations.find(row=>row.facts.stepId==='parse-original');if(parsed.facts.status!=='succeeded')return {schema:'hub-execution-transition/1',state:{stage:'failed'},actions:[{kind:'outcome.error',stepId:'parse-failed',occurrence:0,code:parsed.facts.error?.code??'HOOK_FAILED',facts:{stage:'parse'}}]};return {schema:'hub-execution-transition/1',state:{stage:'done'},actions:[{kind:'delivery.propose',stepId:'deliver',occurrence:0,status:'succeeded',result:parsed.facts.result,references:input.observations.map(row=>row.reference)}]};}";

// Preserve the exact synthetic worker report body while C already holds its
// terminal proof. Auth headers are forwarded but never retained by this fixture.
export async function heldReviewReport(t:any,h:any,holdSuccessful=true){
 let release:()=>void=()=>{};const gate=new Promise<void>(resolve=>{release=resolve;});let held:any;const responses:{operationId:string;status:number;code:string|null}[]=[];
 const server=createServer(async(req,res)=>{try{const parts=[];for await(const chunk of req)parts.push(chunk);const bytes=Buffer.concat(parts),route=/^\/v1\/workers\/operations\/([^/]+)\/report$/.exec(req.url??'');if(route&&bytes.length){const body=JSON.parse(bytes.toString()),row=(await h.db.query('SELECT source_effect FROM operations WHERE operation_id=$1',[route[1]])).rows[0];if(holdSuccessful&&row?.source_effect==='write'&&body.status==='succeeded'){held={operationId:route[1],body};await gate;}}const headers:Record<string,string>={};for(const key of ['authorization','content-type','accept'])if(typeof req.headers[key]==='string')headers[key]=req.headers[key];const response=await fetch(new URL(req.url??'/',h.url),{method:req.method,headers,...(bytes.length?{body:bytes}:{})});const body=Buffer.from(await response.arrayBuffer());if(route){let result:any;try{result=JSON.parse(body.toString());}catch{}responses.push({operationId:route[1],status:response.status,code:result?.error?.code??null});}if(!res.destroyed){res.writeHead(response.status,Object.fromEntries([...response.headers].filter(([key])=>!['connection','transfer-encoding'].includes(key))));res.end(body);}}catch{if(!res.destroyed){res.writeHead(502);res.end('{"error":"Synthetic held report transport failed"}');}}});
 await new Promise<void>(resolve=>server.listen(0,'127.0.0.1',resolve));t.after(async()=>{release();server.closeAllConnections();await new Promise<void>(resolve=>server.close(()=>resolve()));});await h.startWorker('lab-east-01',{CIRCLE_HUB_URL:`http://127.0.0.1:${(server.address() as any).port}`});return {held:()=>held,responses:()=>responses,release};
}
